-- THACH DAU CUOC XU + LI XI TET (19/10/2026, chu game duyet "sua 3 nguon in tien con lai"). Idempotent,
-- MariaDB 10.3 / MySQL 5.7, utf8.   mysql htbb_db < sql/sua_vong_quay_2.sql   (sau sql/sua_vong_quay.sql)
--
-- May chu: real.ThachDauCuoc + com.htbb.pokemon.ThachDauLogic (ky quy, chia tien), com.htbb.pokemon.LiXiLogic
-- + GioiHanQua (tran li xi), data.DatabaseGioiHanQua (CSDL). May chu cung tu tao hai bang duoi luc chay.
--
-- 1. tob_gioi_han_qua     o dem (ma, khoa): so trong ngay + tong ca dot - tran nhan / mo bao li xi, giai lon / dot,
--                         ma li xi moi tai khoan / thiet bi / IP, tong luong khoa / dot. Moi phep cong la mot UPDATE co
--                         dieu kien (nguyen tu).
-- 2. tob_thach_dau_ky_quy cuoc dang giu cua tran dang danh; may tat giua tran -> lan khoi dong sau hoan du hai ben
--                         qua tob_vong_quay_cho_nhan (cong khi dang nhap).
-- 3. Danh muc cau hinh nhom cuoc_xu (lop co_dinh, nhu thue / phi khac; doi khan cap bang server.ini). Mac dinh:
--      thach dau: cap 40, cuoc 1.000 - min(100.000, 2 gio thu nhap o cap thap nhat trong tran), phi 10% ben thang,
--                 hoa hoan du; ap cho 1-1 va nhom (truoc: 1-1 100.000 - 10.000.000 phi 10%, nhom mat ca hai cuoc).
--      bao li xi: nhan 2 / ngay, mo 3 / ngay, 15 / dot; xu 5 - 10% gio, giai lon 100% gio (truoc 1 - 5 trieu xu).
--      ma li xi : 5 - 15 luong KHOA (truoc 10 - 100 luong mo / Pokemon), 1 / tai khoan, 1 tai khoan / thiet bi / IP,
--                 20.000 luong khoa / dot.

CREATE TABLE IF NOT EXISTS `tob_gioi_han_qua` (
  `ma` VARCHAR(40) NOT NULL, `khoa` VARCHAR(80) NOT NULL, `ngay` VARCHAR(8) NOT NULL DEFAULT '',
  `so_ngay` BIGINT NOT NULL DEFAULT 0, `tong` BIGINT NOT NULL DEFAULT 0, `cap_nhat` DATETIME NULL,
  PRIMARY KEY (`ma`, `khoa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_thach_dau_ky_quy` (
  `id_arena` INT NOT NULL, `loai` TINYINT NOT NULL DEFAULT 3,
  `ten0` VARCHAR(40) NOT NULL DEFAULT '', `id0` INT NOT NULL DEFAULT 0,
  `ten1` VARCHAR(40) NOT NULL DEFAULT '', `id1` INT NOT NULL DEFAULT 0,
  `cuoc` BIGINT NOT NULL DEFAULT 0, `luc` DATETIME NOT NULL, PRIMARY KEY (`id_arena`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Bang hoan tien offline (cung tao trong sql/sua_vong_quay.sql; lap lai cho chay rieng duoc).
CREATE TABLE IF NOT EXISTS `tob_vong_quay_cho_nhan` (
  `charname` VARCHAR(40) NOT NULL, `xu` BIGINT NOT NULL DEFAULT 0, `luong` BIGINT NOT NULL DEFAULT 0,
  `ly_do` VARCHAR(255) NOT NULL DEFAULT '', `cap_nhat` DATETIME NOT NULL, PRIMARY KEY (`charname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `cau_hinh_danh_muc` (`khoa` VARCHAR(64) NOT NULL, `nhom` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `kieu` VARCHAR(12) NOT NULL, `mac_dinh` VARCHAR(255) NOT NULL DEFAULT '', `gioi_han` TEXT NOT NULL, `ap_dung` VARCHAR(16) NOT NULL, `nhay` TINYINT NOT NULL DEFAULT 0, `khoa_prod` TINYINT NOT NULL DEFAULT 0, `chi_doc` TINYINT NOT NULL DEFAULT 0, `bang` VARCHAR(16) NOT NULL DEFAULT 'cau_hinh', `dung_o` VARCHAR(10) NOT NULL DEFAULT 'server', `nguon` VARCHAR(255) NOT NULL DEFAULT '', `thu_tu` INT NOT NULL DEFAULT 0, `lop` VARCHAR(10) NOT NULL DEFAULT 'chinh', `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`khoa`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `cau_hinh_nhom` (`ma` VARCHAR(20) NOT NULL, `ten` VARCHAR(160) NOT NULL DEFAULT '', `mo_ta` TEXT NOT NULL, `thu_tu` INT NOT NULL DEFAULT 0, `an` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`ma`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `cau_hinh_nhom` (`ma`, `ten`, `mo_ta`, `thu_tu`, `an`) VALUES ('cuoc_xu', 'Thách đấu cược xu & lì xì (cố định)', 'Thách đấu cược xu 1-1 và nhóm (ký quỹ hai bên, phí bên thắng là hố hút, hoà hoàn đủ, mức theo cấp) và lì xì Tết (bao: trần nhận / mở theo ngày và đợt, xu theo giờ thu nhập; mã: lượng khoá, mỗi tài khoản / thiết bị / IP một lần, trần tổng). Công thức kinh tế cốt lõi: cố định (đổi khẩn cấp bằng server.ini).', 7, 1) ON DUPLICATE KEY UPDATE `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `thu_tu`=VALUES(`thu_tu`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('thach_dau.bat', 'cuoc_xu', 'Thách đấu cược xu: bật', '0 = không nhận trận cược mới (trận đang đánh vẫn chia như thường).', 'co', '1', '{}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.ThachDauCuoc / com.htbb.pokemon.ThachDauLogic', 98, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('thach_dau.cap_toi_thieu', 'cuoc_xu', 'Thách đấu cược xu: cấp tối thiểu', 'Mọi người trong trận (1-1 hoặc cả hai nhóm). Luôn cộng thêm cổng chống clone: cấp hiệu lực = max(hai số).', 'so', '40', '{"min": 0, "max": 200}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.ThachDauCuoc / com.htbb.pokemon.ThachDauLogic', 99, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('thach_dau.cuoc_toi_thieu', 'cuoc_xu', 'Thách đấu cược xu: cược tối thiểu (xu)', 'Mỗi bên.', 'so', '1000', '{"min": 1, "max": 2000000000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.ThachDauCuoc / com.htbb.pokemon.ThachDauLogic', 100, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
INSERT INTO `cau_hinh_danh_muc` (`khoa`, `nhom`, `ten`, `mo_ta`, `kieu`, `mac_dinh`, `gioi_han`, `ap_dung`, `nhay`, `khoa_prod`, `chi_doc`, `bang`, `dung_o`, `nguon`, `thu_tu`, `lop`, `an`) VALUES ('thach_dau.cuoc_toi_da', 'cuoc_xu', 'Thách đấu cược xu: cược tối đa (xu)', 'Trần tuyệt đối mỗi bên; trần thật = min(số này, số giờ dưới × thu nhập 1 giờ ở cấp thấp nhất trong trận).', 'so', '100000', '{"min": 1, "max": 2000000000}', 'ngay', 0, 0, 0, 'cau_hinh', 'server', 'real.ThachDauCuoc / com.htbb.pokemon.ThachDauLogic', 101, 'co_dinh', 1) ON DUPLICATE KEY UPDATE `nhom`=VALUES(`nhom`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `kieu`=VALUES(`kieu`), `mac_dinh`=VALUES(`mac_dinh`), `gioi_han`=VALUES(`gioi_han`), `ap_dung`=VALUES(`ap_dung`), `nhay`=VALUES(`nhay`), `khoa_prod`=VALUES(`khoa_prod`), `chi_doc`=VALUES(`chi_doc`), `bang`=VALUES(`bang`), `dung_o`=VALUES(`dung_o`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `lop`=VALUES(`lop`), `an`=VALUES(`an`);
